package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class MappingIterator_hasNextValue_TriageGen2Test {

    private MappingIterator<Object> iterator;
    private JsonParser mockParser;

    @Before
    public void setUp() {
        // Since MappingIterator is typically created via ObjectMapper, 
        // we use reflection to instantiate and inject dependencies for testing the specific logic.
        iterator = Mockito.mock(MappingIterator.class, Mockito.CALLS_REAL_METHODS);
        mockParser = mock(JsonParser.class);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testHasNextValue_ParserIsNull() throws Exception {
        setPrivateField(iterator, "_parser", null);
        setPrivateField(iterator, "_hasNextChecked", false);

        assertFalse(iterator.hasNextValue());
    }

    @Test
    public void testHasNextValue_AlreadyChecked() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", true);

        assertTrue(iterator.hasNextValue());
        verify(mockParser, never()).getCurrentToken();
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenNotNull() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", false);
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        assertTrue(iterator.hasNextValue());
        verify(mockParser).getCurrentToken();

        // Verify state change
        Field checkedField = iterator.getClass().getDeclaredField("_hasNextChecked");
        checkedField.setAccessible(true);
        assertTrue((Boolean) checkedField.get(iterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_NextTokenValid() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", false);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        assertTrue(iterator.hasNextValue());
        verify(mockParser).nextToken();
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_NextTokenNull_CloseParserTrue() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", false);
        setPrivateField(iterator, "_closeParser", true);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(null);

        assertFalse(iterator.hasNextValue());
        verify(mockParser).close();

        // Verify parser is nulled out
        Field parserField = iterator.getClass().getDeclaredField("_parser");
        parserField.setAccessible(true);
        assertNull(parserField.get(iterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_NextTokenEndArray_CloseParserFalse() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", false);
        setPrivateField(iterator, "_closeParser", false);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(iterator.hasNextValue());
        verify(mockParser, never()).close();

        Field parserField = iterator.getClass().getDeclaredField("_parser");
        parserField.setAccessible(true);
        assertNull(parserField.get(iterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_NextTokenEndArray_CloseParserTrue() throws Exception {
        setPrivateField(iterator, "_parser", mockParser);
        setPrivateField(iterator, "_hasNextChecked", false);
        setPrivateField(iterator, "_closeParser", true);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(iterator.hasNextValue());
        verify(mockParser).close();
    }
}
